import {Rom,BASE,scanRom,traceSong,collectDependencies,isSongEntry} from './music-parser.js';
import {readAuthoring,usedAuthoring} from './authoring-model.js';
import {STOCK_FIRE_RED_SHA} from './verified-frlg.js';

export const MUSIC_FORMAT='shattered-music';
export function bytes64(bytes){let out='';for(let i=0;i<bytes.length;i+=16384)out+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(out);}
export function from64(s){if(typeof s!=='string'||s.length>16e6||!/^[A-Za-z0-9+/]*={0,2}$/.test(s))throw Error('Invalid music asset encoding.');return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}
function mergeSpans(spans){const out=[];for(const s of spans.sort((a,b)=>a.start-b.start)){const prior=out.at(-1);if(prior&&s.start<=prior.end)prior.end=Math.max(prior.end,s.end);else out.push({...s});}return out;}
export function extractMusic(bytes,table,songId,{name='Track '+songId,sourceHash='',sourceName='Uploaded ROM'}={}){
 const r=new Rom(bytes),song=traceSong(r,table,songId),deps=collectDependencies(r,song);if(!song.trackCount)throw Error('This entry contains no music tracks.');
 const nodes=[],banks=new Map(),rows=new Map();
 // Native split banks can share physical rows. Preserve their relative bases
 // inside one sparse allocation rather than losing an aliased row in a copy.
 const bankSources=[...new Set([song.bank,...deps.rows.map(row=>row.bank),...deps.pointers.filter(p=>p.kind==='subbank').map(p=>p.target)])];
 for(const range of mergeSpans(bankSources.map(start=>({start,end:start+1536}))))nodes.push({type:'bank',source:range.start,length:range.end-range.start,data:new Uint8Array(range.end-range.start)});
 for(const bank of bankSources){const node=nodes.find(n=>n.type==='bank'&&bank>=n.source&&bank+1536<=n.source+n.length);banks.set(bank,{node,within:bank-node.source});}
 for(const row of deps.rows){const {node}=banks.get(row.bank),offset=row.start-node.source;node.data.set(bytes.subarray(row.start,row.start+12),offset);rows.set(row.start,{node,offset});}
 const raw=mergeSpans([{start:song.header,end:song.header+8+song.trackCount*4},...song.spans,...deps.samples.map(s=>({start:s.start,end:s.start+s.length})),...deps.waves.map(s=>({start:s.start,end:s.start+s.length})),...deps.keymaps.map(s=>({start:s.start,end:s.start+s.length}))]);
 for(const range of raw)nodes.push({type:'raw',source:range.start,length:range.end-range.start,data:bytes.slice(range.start,range.end)});
 let length=0;for(const n of nodes){n.offset=(length+3)&~3;length=n.offset+n.length;}if(length>12*1024*1024)throw Error('This music asset exceeds 12 MB.');const packed=new Uint8Array(length),v=new DataView(packed.buffer);for(const n of nodes)packed.set(n.data,n.offset);
 const locate=(address,{bank=false}={})=>{if(bank){const n=banks.get(address);if(!n)throw Error('A music bank dependency is missing.');return n.node.offset+n.within;}for(const [start,row]of rows)if(address>=start&&address<start+12)return row.node.offset+row.offset+address-start;const n=nodes.find(n=>n.type==='raw'&&address>=n.source&&address<n.source+n.length);if(!n)throw Error('A music sequence or sample dependency is missing.');return n.offset+address-n.source;};
 const pointers=[];for(const p of [...song.pointers,...deps.pointers]){if(p.kind==='song-header')continue;const at=locate(p.offset),target=locate(p.target,{bank:p.kind==='voice-bank'||p.kind==='subbank'});v.setUint32(at,target,true);pointers.push(at);}
 const asset={format:MUSIC_FORMAT,version:1,name,sourceHash,sourceName,sourceSongId:songId,sourceTable:table,trackCount:song.trackCount,header:locate(song.header),bytes:bytes64(packed),pointers:[...new Set(pointers)].sort((a,b)=>a-b),sampleCount:deps.samples.length,sourceBytes:length};validateMusicAsset(asset);return asset;
}
export function unpackMusic(asset){const bytes=from64(asset.bytes),out=new Uint8Array(bytes.length+8);out.set(bytes);const v=new DataView(out.buffer);for(const at of asset.pointers){if(!Number.isInteger(at)||at<0||at+4>bytes.length)throw Error('A music relocation lies outside its asset.');const to=v.getUint32(at,true);if(to>=bytes.length)throw Error('A music relocation target is missing.');v.setUint32(at,BASE+to,true);}v.setUint32(bytes.length,BASE+asset.header,true);return{bytes:out,table:bytes.length};}
export function validateMusicAsset(asset){if(!asset||asset.format!==MUSIC_FORMAT||asset.version!==1||!Array.isArray(asset.pointers)||asset.pointers.length>40000||!Number.isInteger(asset.header)||asset.header<0)throw Error('Not a supported music asset.');const {bytes,table}=unpackMusic(asset),r=new Rom(bytes);if(!isSongEntry(r,table))throw Error('Invalid music asset header.');const song=traceSong(r,table,0,{maxStates:100000}),deps=collectDependencies(r,song),actual=new Set([...song.pointers,...deps.pointers].filter(p=>p.kind!=='song-header').map(p=>p.offset)),given=new Set(asset.pointers);if(actual.size!==given.size||[...actual].some(p=>!given.has(p)))throw Error('The music relocation list does not match its decoded dependencies.');return{song,deps};}
export function musicTables(bytes){const candidates=scanRom(new Rom(bytes)).filter(t=>t.count>=4&&t.count<4096);if(!candidates.length)throw Error('No supported MP2K / Sappy song table was found.');return candidates;}
export function musicProfile(hash){return hash===STOCK_FIRE_RED_SHA?{table:4862668,count:347,refs:[1954076,1954128,1954204,1954288,1954340],players:4862620,maxTracks:10}:null;}
export function installMusic(project,reader,sourceHash,output){let profile=musicProfile(sourceHash);const used=usedAuthoring(project).music,tracks=readAuthoring(project).music.filter(t=>used.has(t.id)),ids=new Map(),reports=[];let imported=[];
 for(const t of tracks){const checked=validateMusicAsset(t.asset);if(t.asset.sourceHash===sourceHash&&Number.isInteger(t.asset.sourceSongId)&&isSongEntry(new Rom(reader.bytes),t.asset.sourceTable+t.asset.sourceSongId*8)){ids.set(t.id,t.asset.sourceSongId);reports.push('Music: '+t.name+' · reuse native track '+t.asset.sourceSongId);continue;}if(!profile)profile=discoverMusicTarget(reader);if(!profile)throw Error('The opened ROM’s music-player table references could not be verified.');if(checked.song.trackCount>profile.maxTracks)throw Error(t.name+': too many tracks for this target music player.');imported.push(t);}
 if(imported.length){const p=profile;if(p.refs.some(at=>reader.u32(at)!==BASE+p.table||p.players!==null&&reader.u32(at-4)!==BASE+p.players))throw Error('The target music table references failed verification.');if(p.count+imported.length>65535)throw Error('The song ID limit was exceeded.');const table=new Uint8Array((p.count+imported.length)*8);table.set(reader.bytes.slice(p.table,p.table+p.count*8));const tv=new DataView(table.buffer);
  for(const [index,t]of imported.entries()){const packed=from64(t.asset.bytes),at=output.allocate(packed,'Music: '+t.name),v=new DataView(packed.buffer);for(const field of t.asset.pointers)v.setUint32(field,BASE+at+v.getUint32(field,true),true);output.write(at,packed);const id=p.count+index;tv.setUint32(id*8,BASE+at+t.asset.header,true);tv.setUint16(id*8+4,0,true);tv.setUint16(id*8+6,0,true);ids.set(t.id,id);reports.push('Music '+id+': '+t.name+' · '+packed.length+' bytes including used samples');}
  const at=output.allocate(table,'Expanded music table');for(const ref of p.refs)output.int(ref,BASE+at);
 }return{ids,reports,imported:imported.length,unused:readAuthoring(project).music.length-tracks.length};}

const targetMusicCache=new WeakMap();
export function discoverMusicTarget(reader){if(targetMusicCache.has(reader))return targetMusicCache.get(reader);const r=new Rom(reader.bytes),tables=[],literalUses=new Set();
 // Retain references only for actual song tables, rather than indexing every
 // ROM pointer. This keeps native compilation bounded on Android.
 for(let at=512;at<reader.size-32;at+=4){if(!isSongEntry(r,at))continue;let count=1;while(count<65534&&isSongEntry(r,at+count*8))count++;if(count>=4)tables.push({table:at,count,references:[]});at+=(count-1)*8;}
 const byAddress=new Map(tables.map(t=>[t.table,t]));let lastRef=512;for(let at=512;at<reader.size-4;at+=4){const t=byAddress.get(reader.u32(at)-BASE);if(t){t.references.push(at);lastRef=Math.max(lastRef,at);}}
 for(let at=512;at<Math.min(reader.size-2,lastRef+2);at+=2){const op=reader.u16(at);if((op&0xf800)===0x4800)literalUses.add(((at+4)&~3)+(op&255)*4);}const found=[];
 for(const s of tables){const refs=s.references.filter(at=>at>=516&&literalUses.has(at));if(refs.length<2)continue;let maxTracks=0;for(let id=0;id<s.count;id++)if(reader.u16(s.table+id*8+4)===0){const h=reader.ptr(s.table+id*8);if(reader.valid(h,8))maxTracks=Math.max(maxTracks,reader.u8(h));}if(!maxTracks)continue;found.push({table:s.table,count:s.count,refs,players:null,maxTracks:Math.min(10,maxTracks)});}
 found.sort((a,b)=>b.count-a.count);const result=found.length&&(!found[1]||found[0].count>found[1].count)?found[0]:null;targetMusicCache.set(reader,result);return result;}
